package org.solarelevation.alarm;
import android.content.*;
import android.media.*;
import android.os.*;
import android.util.*;
import java.util.*;
public final class SolarAlarmOutputRouteGuard {
public static final String SOURCE_ID="SolarAlarmOutputRouteGuard_v20261105T212400Z";
private static final int[] PREFERENCE={AudioDeviceInfo.TYPE_BLUETOOTH_A2DP,AudioDeviceInfo.TYPE_BLE_HEADSET,AudioDeviceInfo.TYPE_BLE_SPEAKER,AudioDeviceInfo.TYPE_BLE_BROADCAST,AudioDeviceInfo.TYPE_HEARING_AID,AudioDeviceInfo.TYPE_WIRED_HEADPHONES,AudioDeviceInfo.TYPE_WIRED_HEADSET,AudioDeviceInfo.TYPE_USB_HEADSET,AudioDeviceInfo.TYPE_USB_DEVICE,AudioDeviceInfo.TYPE_USB_ACCESSORY,AudioDeviceInfo.TYPE_BLUETOOTH_SCO};
public static boolean enabled(Context c){return c.getSharedPreferences("audio_output",0).getBoolean("external_only",false);}
public static void setEnabled(Context c,boolean on){c.getSharedPreferences("audio_output",0).edit().putBoolean("external_only",on).apply();}
public static boolean allowed(AudioDeviceInfo d){if(d==null)return false;switch(d.getType()){case AudioDeviceInfo.TYPE_WIRED_HEADSET:case AudioDeviceInfo.TYPE_WIRED_HEADPHONES:case AudioDeviceInfo.TYPE_USB_HEADSET:case AudioDeviceInfo.TYPE_USB_DEVICE:case AudioDeviceInfo.TYPE_USB_ACCESSORY:case AudioDeviceInfo.TYPE_BLUETOOTH_A2DP:case AudioDeviceInfo.TYPE_BLUETOOTH_SCO:case AudioDeviceInfo.TYPE_BLE_HEADSET:case AudioDeviceInfo.TYPE_BLE_SPEAKER:case AudioDeviceInfo.TYPE_BLE_BROADCAST:case AudioDeviceInfo.TYPE_HEARING_AID:return true;default:return false;}}
public static List<AudioDeviceInfo> available(Context c){List<AudioDeviceInfo> out=new ArrayList<>();try{AudioManager m=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);if(m!=null)for(AudioDeviceInfo d:m.getDevices(AudioManager.GET_DEVICES_OUTPUTS))if(allowed(d))out.add(d);}catch(Exception ignored){}return out;}
public static String prereq(Context c){if(!enabled(c))return null;if(Build.VERSION.SDK_INT<36)return "Connected Audio Only requires Android 16 (API 36) to verify every audio output";if(available(c).isEmpty())return "No eligible wired, USB or Bluetooth audio output is connected";return null;}
public static AudioDeviceInfo preferred(Context c){List<AudioDeviceInfo> devices=available(c);if(devices.isEmpty())return null;if(Build.VERSION.SDK_INT>=33){try{AudioManager m=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);AudioAttributes a=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build();for(AudioDeviceInfo d:m.getAudioDevicesForAttributes(a))if(allowed(d))return d;}catch(Exception ignored){}}for(int type:PREFERENCE)for(AudioDeviceInfo d:devices)if(d.getType()==type)return d;return devices.get(0);}
public static boolean routed(Object output){if(Build.VERSION.SDK_INT<36||output==null)return false;try{Object obj=output.getClass().getMethod("getRoutedDevices").invoke(output);if(!(obj instanceof List))return false;List<?> route=(List<?>)obj;if(route.isEmpty())return false;for(Object d:route)if(!(d instanceof AudioDeviceInfo)||!allowed((AudioDeviceInfo)d))return false;return true;}catch(Exception ex){return false;}}
public static String routeDetails(Object output){if(Build.VERSION.SDK_INT<36)return "route inspection requires Android 16";if(output==null)return "no audio output object";try{Object obj=output.getClass().getMethod("getRoutedDevices").invoke(output);if(!(obj instanceof List))return "route unavailable";List<?> list=(List<?>)obj;if(list.isEmpty())return "route not established";StringBuilder b=new StringBuilder();for(Object item:list){if(b.length()>0)b.append("; ");if(item instanceof AudioDeviceInfo){AudioDeviceInfo d=(AudioDeviceInfo)item;b.append(d.getProductName()).append(" type=").append(d.getType()).append(" id=").append(d.getId()).append(" allowed=").append(allowed(d));}else b.append("unknown audio device");}return b.toString();}catch(Exception ex){return "route inspection failed: "+ex.getClass().getSimpleName();}}
public static void event(Context c,String message){String record=System.currentTimeMillis()+" "+message+"\n";synchronized(SolarAlarmOutputRouteGuard.class){SharedPreferences p=c.getSharedPreferences("audio_output_diagnostics",0);String existing=p.getString("events","");p.edit().putString("events",(existing+record).substring(Math.max(0,existing.length()+record.length()-16000))).apply();}Log.i("SolarAlarmAudio",message);}
public static String diagnostics(Context c){StringBuilder b=new StringBuilder("Connected Audio Only: ").append(enabled(c)).append("\n");b.append("Route verification supported: ").append(Build.VERSION.SDK_INT>=36).append("\n");String issue=prereq(c);if(issue!=null)b.append("Playback prerequisite: ").append(issue).append("\n");for(AudioDeviceInfo d:available(c))b.append("Eligible output: ").append(d.getProductName()).append(" type=").append(d.getType()).append(" id=").append(d.getId()).append("\n");b.append("Recent audio routing events:\n").append(c.getSharedPreferences("audio_output_diagnostics",0).getString("events",""));return b.toString();}
private SolarAlarmOutputRouteGuard(){}
}